const items = $input.all();
const candidates = [];

function easternTodayUtc() {
  const parts = Object.fromEntries(
    new Intl.DateTimeFormat('en-US', {
      timeZone: 'America/New_York',
      year: 'numeric', month: '2-digit', day: '2-digit',
    })
      .formatToParts(new Date())
      .filter((part) => part.type !== 'literal')
      .map((part) => [part.type, part.value])
  );
  return Date.UTC(Number(parts.year), Number(parts.month) - 1, Number(parts.day));
}

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

function clean(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

const todayUtc = easternTodayUtc();
const dayMs = 24 * 60 * 60 * 1000;

for (let index = 0; index < items.length; index++) {
  const binary = items[index].binary?.data;
  if (!binary) continue;
  const fileName = binary.fileName || binary.filePath?.split('/').pop() || '';
  const match = fileName.match(/content-candidates-model-eval-(\d{4}-\d{2}-\d{2})\.json$/i);
  if (!match) continue;

  const [year, month, day] = match[1].split('-').map(Number);
  const ageDays = Math.floor((todayUtc - Date.UTC(year, month - 1, day)) / dayMs);
  if (ageDays < 0 || ageDays > 3) continue;

  const buffer = await this.helpers.getBinaryDataBuffer(index, 'data');
  let parsed;
  try {
    parsed = JSON.parse(buffer.toString('utf-8'));
  } catch {
    continue;
  }
  candidates.push({ fileName, fileDate: match[1], ageDays, parsed });
}

if (!candidates.length) {
  throw new Error('No evidence-calibrated candidate JSON file from the last 3 days was found.');
}

candidates.sort((a, b) => {
  const dateCompare = b.fileDate.localeCompare(a.fileDate);
  return dateCompare || b.fileName.localeCompare(a.fileName);
});

const latest = candidates[0];
const source = latest.parsed;
const workflowVersion = Number(source.workflowVersion || 0);
const blockingRiskPattern = /\b(single[- ]source|no independent corroboration|independent corroboration lacking|promotional|unverified|same source family|insufficient corroboration)\b/i;
const verifiedCandidates = [
  ...asArray(source.themeAligned),
  ...asArray(source.emerging),
].filter((candidate) =>
  candidate &&
  candidate.verificationStatus === 'verified' &&
  workflowVersion >= 4.6 &&
  candidate.validation?.strongEvidence === true &&
  candidate.validation?.bundleValid === true &&
  candidate.validation?.semanticEvidenceAligned === true &&
  clean(candidate.evidenceBundleId) !== '' &&
  candidate.validation?.unresolvedBlockingRisk !== true &&
  !asArray(candidate.editorialRisks).some((risk) => blockingRiskPattern.test(String(risk || ''))) &&
  Number(candidate.validation?.independentSourceFamilyCount || 0) >= 2 &&
  asArray(candidate.sources).length >= 2
);

const watchlistCandidates = asArray(source.watchlist).filter(Boolean);

return [{
  json: {
    sourceWorkflowVersion: source.workflowVersion || null,
    sourceCandidateFile: latest.fileName,
    sourceCandidateDate: latest.fileDate,
    sourceCandidateAgeDays: latest.ageDays,
    sourceThemeFile: source.sourceThemeFile || null,
    sourceThemeDate: source.sourceThemeDate || null,
    consolidatedThemes: asArray(source.consolidatedThemes),
    verifiedCandidateCount: verifiedCandidates.length,
    watchlistCandidateCount: watchlistCandidates.length,
    verifiedCandidates,
    watchlistCandidates,
  },
}];

