function clean(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

function sentenceTopic(value) {
  const preserve = new Set([
    'AI', 'API', 'AWS', 'CISA', 'CMMC', 'CVE', 'HIPAA', 'HITRUST', 'IaC',
    'IT', 'NIST', 'OSS', 'OT', 'RMF', 'SCADA', 'SOC', 'Microsoft', 'Entra',
    'Azure', 'Google',
  ]);
  const source = clean(value);
  if (!source) return 'the selected topic';
  return source.split(/\s+/).map((word) => {
    const bare = word.replace(/^[^A-Za-z0-9]+|[^A-Za-z0-9]+$/g, '');
    if (preserve.has(bare) || /^[A-Z0-9]{2,}$/.test(bare)) return word;
    return word.toLowerCase();
  }).join(' ');
}

function planningSubject(value) {
  return sentenceTopic(value)
    .replace(/\s+guidance$/i, '')
    .replace(/\s+principles(?:\s+and\s+practices)?$/i, '')
    .trim() || 'the selected topic';
}

function list(value) {
  return Array.isArray(value) ? value : [];
}

function parseJson(value) {
  const source = clean(value).replace(/```(?:json)?|```/gi, '').trim();
  try {
    return JSON.parse(source);
  } catch {
    const first = source.indexOf('{');
    const last = source.lastIndexOf('}');
    if (first >= 0 && last > first) return JSON.parse(source.slice(first, last + 1));
    return {};
  }
}

function normalized(value) {
  return clean(value).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
}

function clamp(value, minimum, maximum) {
  const number = Number(value);
  return Math.max(minimum, Math.min(maximum, Number.isFinite(number) ? number : minimum));
}

function dedupeText(values) {
  const output = [];
  const seen = new Set();
  for (const value of values.map(clean).filter(Boolean)) {
    const key = normalized(value);
    if (!key || seen.has(key)) continue;
    seen.add(key);
    output.push(value);
  }
  return output;
}

function safeThreatTakeaways() {
  return [
    'Review whether existing telemetry covers the services and behaviors named in the verified evidence.',
    'Test detection logic against documented behavior before changing production controls.',
    'Map affected identities, applications, assets, and trust relationships.',
    'Update response decision points for investigation, containment, and recovery.',
    'Track primary research, vendor guidance, and confirmed indicators as the issue develops.',
  ];
}

function safeEditorialTakeaways(candidate) {
  const topic = clean(candidate.topic);
  const topicPhrase = planningSubject(topic);
  return [
    'Read the primary source alongside the independent coverage before defining the response.',
    `Confirm where ${topicPhrase} affects current assets, processes, accountable owners, and business dependencies.`,
    'Compare current policy and operating practices with the verified guidance.',
    'Document decision criteria, exceptions, testing requirements, and ownership before rollout.',
    'Track updates to both cited sources and revise the plan when the evidence changes.',
  ];
}

const planned = parseJson($json.choices?.[0]?.message?.content);
const source = $('Add Editorial Policy').first().json;
const verified = list(source.verifiedCandidates);
const watchlist = list(source.watchlistCandidates);
const candidateMap = new Map(verified.map((candidate) => [normalized(candidate.topic), candidate]));
const webinarInventoryPresent = list(source.editorialPolicy?.currentWebinarTopics).length > 0;
const allowedPostTypes = new Set(['security', 'technology', 'governance', 'leadership', 'resilience']);
const allowedBrand = new Set(['serket', 'personal_only', 'neutral']);
const selectedTopics = [];
const seenTopics = new Set();
const validationWarnings = [];

for (const proposed of list(planned.selectedTopics)) {
  if (selectedTopics.length >= 5) break;
  const key = normalized(proposed.sourceCandidateTopic);
  const candidate = candidateMap.get(key);
  if (!candidate || seenTopics.has(key)) {
    if (clean(proposed.sourceCandidateTopic)) validationWarnings.push(`Rejected unverified or duplicate selection: ${clean(proposed.sourceCandidateTopic)}`);
    continue;
  }

  const sourceUrlSet = new Set(list(candidate.sources).map((item) => clean(item.url)).filter(Boolean));
  const sourceUrls = [...sourceUrlSet];
  if (sourceUrls.length < 2) {
    validationWarnings.push(`Rejected selection without two exact verified source URLs: ${candidate.topic}`);
    continue;
  }

  const primaryIndustry = clean(proposed.primaryIndustry) || 'general enterprise';
  let postType = clean(proposed.postType).toLowerCase();
  if (!allowedPostTypes.has(postType)) postType = 'technology';
  let brandTreatment = clean(proposed.brandTreatment).toLowerCase();
  if (!allowedBrand.has(brandTreatment)) brandTreatment = 'neutral';
  const broadcast = /broadcast|media/i.test(primaryIndustry);
  if (broadcast && postType !== 'security') brandTreatment = 'personal_only';

  const audience = list(proposed.audience).map(clean).filter(Boolean).slice(0, 5);
  if (!audience.length) audience.push(...list(candidate.targetAudience).map(clean).filter(Boolean).slice(0, 5));

  const topicPhrase = clean(candidate.topic);
  const lowerTopicPhrase = planningSubject(topicPhrase);
  const howWeHelp = `We help organizations assess current practices, define risk-based decisions, assign ownership, and build a measurable roadmap for ${lowerTopicPhrase}.`;
  if (normalized(proposed.howWeHelp) !== normalized(howWeHelp)) {
    validationWarnings.push(`Normalized how-we-help language: ${candidate.topic}`);
  }

  const threatTopic = /\b(malware|ransomware|threat actor|attack campaign|cyberattack|breach|vulnerability|exploit|zero[- ]day|cve-|security advisory)\b/i.test(`${candidate.topic} ${candidate.proposedHeadline}`);
  const practicalTakeaways = threatTopic
    ? safeThreatTakeaways()
    : safeEditorialTakeaways(candidate);
  validationWarnings.push(`Normalized practical takeaways to bounded editorial recommendations: ${candidate.topic}`);

  let webinarReview = clean(proposed.webinarReview).toLowerCase();
  if (!webinarInventoryPresent) webinarReview = 'manual_review_required';
  if (!['clear', 'supports', 'overlaps', 'block', 'manual_review_required'].includes(webinarReview)) {
    webinarReview = 'manual_review_required';
  }

  seenTopics.add(key);
  selectedTopics.push({
    priority: selectedTopics.length + 1,
    sourceCandidateTopic: candidate.topic,
    sourceCandidateRank: candidate.rank,
    workingHeadline: clean(candidate.proposedHeadline),
    primaryIndustry,
    secondaryIndustries: list(proposed.secondaryIndustries).map(clean).filter(Boolean).slice(0, 5),
    postType,
    brandTreatment,
    brandReason: clean(proposed.brandReason),
    audience,
    editorialAngle: `Examine the verified guidance, the leadership decisions it creates, and how organizations can evaluate current practices for ${lowerTopicPhrase}.`,
    concreteProblem: `Leaders need a defensible operating approach to ${lowerTopicPhrase}.`,
    leadershipDecision: `Define the scope, ownership, decision criteria, and validation measures for ${lowerTopicPhrase}.`,
    practicalTakeaways,
    howWeHelp,
    sourceUrls,
    webinarReview,
    webinarNotes: clean(proposed.webinarNotes) || (webinarInventoryPresent ? '' : 'Compare against the current webinar calendar before drafting.'),
    imageDirection: `Show a leadership review of ${lowerTopicPhrase}, organized around scope, ownership, evidence, and validation.`,
    targetCharacterRange: {
      minimum: Math.round(clamp(proposed.targetCharacterRange?.minimum, 1200, 2200)),
      maximum: Math.round(clamp(proposed.targetCharacterRange?.maximum, 1800, 2800)),
    },
    confidence: clamp(proposed.confidence, 0, 1),
    editorialRisks: dedupeText([
      ...list(candidate.editorialRisks),
      ...list(proposed.editorialRisks),
    ]),
    verifiedEvidence: {
      sourceCount: list(candidate.sources).length,
      sourceQualityScore: candidate.scores?.sourceQuality ?? null,
      candidateScore: candidate.scores?.total ?? null,
      candidateConfidence: candidate.confidence ?? null,
    },
  });
}

function researchGap(candidate) {
  const risks = list(candidate.editorialRisks).map(clean).filter(Boolean);
  const primaryCount = Number(candidate.validation?.primarySourceCount || 0);
  const independentCount = Number(candidate.validation?.credibleIndependentSourceCount || 0);
  const requiredSourceTypes = [];
  if (primaryCount < 1) requiredSourceTypes.push('Primary authoritative source');
  if (independentCount < 1) requiredSourceTypes.push('Credible independent corroboration');
  if (!requiredSourceTypes.length) requiredSourceTypes.push('Direct source review and claim verification');
  return {
    topic: clean(candidate.topic),
    reason: risks.join('; ') || 'Candidate did not pass the verified-evidence gate.',
    requiredSourceTypes,
    suggestedQueries: [
      `${clean(candidate.topic)} official advisory announcement`,
      `${clean(candidate.topic)} independent enterprise analysis`,
      `${clean(candidate.topic)} implementation evidence case study`,
    ],
    possibleIndustries: [...source.editorialPolicy.activeMarketPreferences, ...source.editorialPolicy.openIndustryExamples].slice(0, 10),
  };
}

const researchPriorities = watchlist.slice(0, 5).map(researchGap);
const deferredTopics = [
  ...list(planned.deferredTopics).map((item) => ({ topic: clean(item.topic), reason: clean(item.reason) })).filter((item) => item.topic),
  ...watchlist.map((item) => ({ topic: clean(item.topic), reason: 'Watchlist only. More evidence is required before editorial selection.' })),
].filter((item, index, array) => array.findIndex((other) => normalized(other.topic) === normalized(item.topic)) === index);

let status = 'insufficient_verified_topics';
if (selectedTopics.length >= 5) status = 'ready';
else if (selectedTopics.length > 0) status = 'partial';

const generatedAt = new Date().toISOString();
return [{
  json: {
    generatedAt,
    status,
    plannerVersion: '1.6.3',
    sourceWorkflowVersion: source.sourceWorkflowVersion,
    sourceCandidateFile: source.sourceCandidateFile,
    sourceCandidateDate: source.sourceCandidateDate,
    sourceThemeFile: source.sourceThemeFile,
    verifiedCandidateCount: verified.length,
    watchlistCandidateCount: watchlist.length,
    selectedTopicCount: selectedTopics.length,
    portfolioRationale: selectedTopics.length
      ? `${selectedTopics.length} ${selectedTopics.length === 1 ? 'topic' : 'topics'} selected from topic-covered, evidence-verified candidates. Industry preferences were applied without fixed quotas.`
      : 'No candidates passed the topic-coverage and verified-evidence gates. Research must continue before drafting.',
    selectedTopics,
    deferredTopics,
    researchPriorities,
    policySummary: {
      fixedIndustryQuotas: false,
      activeMarketsArePreferenceOnly: true,
      automaticPublishingAllowed: false,
      webinarInventoryPresent,
    },
    validation: {
      selectedOnlyFromVerifiedCandidates: true,
      exactSourceUrlsRequired: true,
      rejectedSelectionCount: validationWarnings.length,
      warnings: validationWarnings,
    },
  },
}];

const plan = $json;
const parts = Object.fromEntries(
  new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/New_York',
    year: 'numeric', month: '2-digit', day: '2-digit',
  })
    .formatToParts(new Date())
    .filter((part) => part.type !== 'literal')
    .map((part) => [part.type, part.value])
);
const date = `${parts.year}-${parts.month}-${parts.day}`;
const lines = [
  '# Weekly LinkedIn Editorial Plan', '',
  'Planner version 1.6.3', '',
  `Source workflow version ${plan.sourceWorkflowVersion || 'unknown'}`, '',
  `Generated ${plan.generatedAt}`, '',
  `Status ${plan.status}`, '',
  `Candidate source ${plan.sourceCandidateFile}`, '',
  `Verified candidates ${plan.verifiedCandidateCount}`, '',
  `Watchlist candidates ${plan.watchlistCandidateCount}`, '',
  '## Portfolio decision', '',
  plan.portfolioRationale, '',
];

if (!plan.selectedTopics.length) {
  lines.push('## Selected post briefs', '', 'No topics passed the verified-evidence gate. Do not draft or publish posts from this run.', '');
} else {
  lines.push('## Selected post briefs', '');
  for (const item of plan.selectedTopics) {
    lines.push(
      `### ${item.priority}. ${item.workingHeadline}`, '',
      `Source candidate  ${item.sourceCandidateTopic}`, '',
      `Primary industry  ${item.primaryIndustry}`, '',
      `Post type  ${item.postType}`, '',
      `Brand treatment  ${item.brandTreatment}`, '',
      `Audience  ${item.audience.join(', ')}`, '',
      `Editorial angle  ${item.editorialAngle}`, '',
      `Concrete problem  ${item.concreteProblem}`, '',
      `Leadership decision  ${item.leadershipDecision}`, '',
      'Practical takeaways', '',
      ...item.practicalTakeaways.map((value) => `- ${value}`), '',
      `How we help  ${item.howWeHelp}`, '',
      `Webinar review  ${item.webinarReview}`, '',
      `Webinar notes  ${item.webinarNotes}`, '',
      `Image direction  ${item.imageDirection}`, '',
      `Target length  ${item.targetCharacterRange.minimum} to ${item.targetCharacterRange.maximum} characters`, '',
      'Verified sources', '',
      ...item.sourceUrls.map((value) => `- ${value}`), ''
    );
  }
}

lines.push('## Research priorities', '');
if (!plan.researchPriorities.length) {
  lines.push('No research gaps were generated.', '');
} else {
  for (const item of plan.researchPriorities) {
    lines.push(
      `### ${item.topic}`, '',
      `Reason  ${item.reason}`, '',
      'Required evidence', '',
      ...item.requiredSourceTypes.map((value) => `- ${value}`), '',
      'Suggested searches', '',
      ...item.suggestedQueries.map((value) => `- ${value}`), ''
    );
  }
}

lines.push(
  '## Guardrails', '',
  '- Industries are selected dynamically. There are no weekly sector quotas.',
  '- Active client markets provide a relevance boost but never public evidence.',
  '- Watchlist items cannot become post briefs.',
  '- Webinar overlap requires review before drafting.',
  '- This workflow does not draft or publish LinkedIn posts.', ''
);

function binaryItem(fileName, contents, mimeType) {
  return {
    json: { fileName, status: plan.status, selectedTopicCount: plan.selectedTopicCount },
    binary: {
      data: {
        data: Buffer.from(contents, 'utf-8').toString('base64'),
        mimeType,
        fileName,
      },
    },
  };
}

return [
  binaryItem(`linkedin-editorial-plan-model-eval-${date}.md`, `${lines.join('\n').trim()}\n`, 'text/markdown'),
  binaryItem(`linkedin-editorial-plan-model-eval-${date}.json`, `${JSON.stringify(plan, null, 2)}\n`, 'application/json'),
];

const proof=JSON.parse($('Require Current Candidate Artifact').first().json.stdout);
const items=$input.all();if(items.length!==1||items[0].json.sourceCandidateFile!==proof.candidate.fileName||items[0].json.sourceThemeFile!==proof.privacy.fileName)throw Error('Planner artifact handoff mismatch');
return items;
